import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterModule } from '@angular/router';
import { AuthService, LoginRequest } from '../../services/auth.service';

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterModule],
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent implements OnInit {
  credentials: LoginRequest = {
    email: '',
    password: ''
  };

  loading = false;
  error: string | null = null;
  showPassword = false;

  constructor(
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    // If user is already authenticated, redirect to trips
    this.authService.isAuthenticated$.subscribe(isAuth => {
      if (isAuth) {
        this.router.navigate(['/trips']);
      }
    });
  }

  onSubmit(): void {
    if (!this.validateForm()) {
      return;
    }

    this.loading = true;
    this.error = null;

    this.authService.login(this.credentials).subscribe({
      next: (response) => {
        this.loading = false;
        // Navigation will be handled by the auth service and guards
        this.router.navigate(['/trips']);
      },
      error: (error) => {
        this.loading = false;
        this.error = error.error?.message || 'Login failed. Please check your credentials and try again.';
        console.error('Login error:', error);
      }
    });
  }

  validateForm(): boolean {
    if (!this.credentials.email?.trim()) {
      this.error = 'Email is required';
      return false;
    }

    if (!this.isValidEmail(this.credentials.email)) {
      this.error = 'Please enter a valid email address';
      return false;
    }

    if (!this.credentials.password?.trim()) {
      this.error = 'Password is required';
      return false;
    }

    if (this.credentials.password.length < 6) {
      this.error = 'Password must be at least 6 characters long';
      return false;
    }

    this.error = null;
    return true;
  }

  isValidEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  togglePasswordVisibility(): void {
    this.showPassword = !this.showPassword;
  }

  fillDemoCredentials(): void {
    this.credentials.email = 'admin@travlr.com';
    this.credentials.password = 'admin123';
    this.error = null;
  }

  clearForm(): void {
    this.credentials = {
      email: '',
      password: ''
    };
    this.error = null;
  }
}

<div class="login-container">
  <div class="container">
    <div class="row justify-content-center align-items-center min-vh-100">
      <div class="col-lg-5 col-md-7 col-sm-9">
        <!-- Login Card -->
        <div class="card shadow-lg border-0 login-card">
          <!-- Header -->
          <div class="card-header text-center bg-primary text-white">
            <div class="login-header">
              <i class="fas fa-plane fa-3x mb-3"></i>
              <h2 class="fw-bold mb-1">Travlr Admin</h2>
              <p class="mb-0 opacity-75">Sign in to manage travel packages</p>
            </div>
          </div>

          <!-- Body -->
          <div class="card-body p-4">
            <!-- Demo Credentials Banner -->
            <div class="alert alert-info border-0 mb-4" role="alert">
              <div class="d-flex align-items-center">
                <i class="fas fa-info-circle me-2"></i>
                <div class="flex-grow-1">
                  <small class="fw-semibold">Demo Access Available</small>
                  <br>
                  <small>Use the demo button below for quick access</small>
                </div>
                <button 
                  type="button" 
                  class="btn btn-sm btn-outline-info"
                  (click)="fillDemoCredentials()"
                  [disabled]="loading">
                  <i class="fas fa-user-cog me-1"></i>Demo Login
                </button>
              </div>
            </div>

            <!-- Error Message -->
            <div *ngIf="error" class="alert alert-danger alert-dismissible fade show" role="alert">
              <i class="fas fa-exclamation-triangle me-2"></i>{{ error }}
              <button type="button" class="btn-close" (click)="error = null"></button>
            </div>

            <!-- Login Form -->
            <form (ngSubmit)="onSubmit()" #loginForm="ngForm" novalidate>
              <!-- Email Field -->
              <div class="mb-3">
                <label for="email" class="form-label fw-semibold">
                  <i class="fas fa-envelope me-1"></i>Email Address
                </label>
                <input
                  type="email"
                  class="form-control form-control-lg"
                  id="email"
                  name="email"
                  [(ngModel)]="credentials.email"
                  placeholder="Enter your email"
                  autocomplete="email"
                  required>
              </div>

              <!-- Password Field -->
              <div class="mb-4">
                <label for="password" class="form-label fw-semibold">
                  <i class="fas fa-lock me-1"></i>Password
                </label>
                <div class="input-group">
                  <input
                    [type]="showPassword ? 'text' : 'password'"
                    class="form-control form-control-lg"
                    id="password"
                    name="password"
                    [(ngModel)]="credentials.password"
                    placeholder="Enter your password"
                    autocomplete="current-password"
                    required>
                  <button
                    type="button"
                    class="btn btn-outline-secondary"
                    (click)="togglePasswordVisibility()"
                    [disabled]="loading">
                    <i [class]="showPassword ? 'fas fa-eye-slash' : 'fas fa-eye'"></i>
                  </button>
                </div>
              </div>

              <!-- Submit Button -->
              <div class="d-grid gap-2 mb-3">
                <button
                  type="submit"
                  class="btn btn-primary btn-lg"
                  [disabled]="loading || !loginForm.form.valid">
                  <span *ngIf="loading" class="spinner-border spinner-border-sm me-2"></span>
                  <i *ngIf="!loading" class="fas fa-sign-in-alt me-2"></i>
                  {{ loading ? 'Signing In...' : 'Sign In' }}
                </button>
              </div>

              <!-- Clear Form Button -->
              <div class="d-grid">
                <button
                  type="button"
                  class="btn btn-outline-secondary"
                  (click)="clearForm()"
                  [disabled]="loading">
                  <i class="fas fa-eraser me-2"></i>Clear Form
                </button>
              </div>
            </form>
          </div>

          <!-- Footer -->
          <div class="card-footer bg-light text-center">
            <small class="text-muted">
              Don't have an account? 
              <a routerLink="/register" class="text-decoration-none">
                <i class="fas fa-user-plus me-1"></i>Register here
              </a>
            </small>
          </div>
        </div>

        <!-- Additional Info -->
        <div class="text-center mt-4">
          <div class="card bg-light border-0">
            <div class="card-body py-3">
              <h6 class="card-title mb-2">
                <i class="fas fa-shield-alt me-2"></i>Secure Admin Access
              </h6>
              <small class="text-muted">
                This is a secure area for authorized administrators only. 
                All login attempts are monitored and logged.
              </small>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>
